INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(17818, 'plPL', 'Golem. Polecenie. Raport o stanie operacyjnym.', 'Golem. Polecenie. Raport o stanie operacyjnym.', 0),
(17820, 'plPL', 'Ta jednostka działa obecnie z dziewięćdziesięciopięcioprocentową sprawnością operacyjną.', '', 0),
(17821, 'plPL', 'Ta jednostka działa obecnie w normalnych parametrach.', '', 0),
(17839, 'plPL', 'Ruchy golema wydają się zgodne ze specyfikacją.', 'Ruchy golema wydają się zgodne ze specyfikacją.', 0),
(17840, 'plPL', 'Ucieszę się, gdy końcowe testy tej jednostki dobiegną końca.', 'Ucieszę się, gdy końcowe testy tej jednostki dobiegną końca.', 0),
(17841, 'plPL', 'Po tym teście mobilności zostanie nam już tylko końcowa kontrola uzbrojenia.', 'Po tym teście mobilności zostanie nam już tylko końcowa kontrola uzbrojenia.', 0),
(18030, 'plPL', 'Pierwszy oddział gotowy do boju!', 'Pierwszy oddział gotowy do boju!', 0),
(18031, 'plPL', 'Czysto!', 'Czysto!', 0),
(18032, 'plPL', 'Jesteśmy gotowi bronić Oka!', 'Jesteśmy gotowi bronić Oka!', 0),
(18035, 'plPL', 'Drugi oddział gotowy do walki!', 'Drugi oddział gotowy do walki!', 0),
(18036, 'plPL', 'Wróg się przez nas nie przedrze!', 'Wróg się przez nas nie przedrze!', 0),
(18037, 'plPL', 'Nasze ostrza i zaklęcia są w gotowości!', 'Nasze ostrza i zaklęcia są w gotowości!', 0),
(18038, 'plPL', 'Trzeci oddział melduje się!', 'Trzeci oddział melduje się!', 0),
(18039, 'plPL', 'Nie okażemy wrogom litości!', 'Nie okażemy wrogom litości!', 0),
(18040, 'plPL', 'Nasza obrona jest w gotowości!', 'Nasza obrona jest w gotowości!', 0),
(18045, 'plPL', 'Spocznij!', 'Spocznij!', 0),
(18046, 'plPL', 'Zachowajcie czujność.', 'Zachowajcie czujność.', 0),
(18047, 'plPL', 'Dobrze.', 'Dobrze.', 0),
(18048, 'plPL', 'Doskonała robota.', 'Doskonała robota.', 0),
(18049, 'plPL', 'Wasza postawa napawa mnie dumą.', 'Wasza postawa napawa mnie dumą.', 0),
(18259, 'plPL', 'Pokłońcie się mojej woli.', '', 0),
(19003, 'plPL', 'Przetrwaliście starcie z kilkoma z moich najlepszych doradców... ale nikt nie oprze się potędze Krwawego Młota. Oto lord Sanguinar!', '', 0),
(19004, 'plPL', 'Capernian dopilnuje, by wasz pobyt tutaj był krótki.', '', 0),
(19005, 'plPL', 'Dobra robota, okazaliście się godni, by zmierzyć się z moim mistrzem inżynierem, Telonicusem.', '', 0),
(19006, 'plPL', 'Zobaczmy, jak wytrzymają wasze nerwy w starciu z Zaciemniaczem, Thaladredem!', '', 0),
(19053, 'plPL', 'Jak widzicie, mam w swoim arsenale wiele broni...', '', 0),
(19060, 'plPL', 'Może was nie doceniłem. Byłoby nieuczciwie kazać wam walczyć ze wszystkimi czterema doradcami naraz, ale... mój lud nigdy nie zaznał uczciwego traktowania. Ja tylko odwzajemniam przysługę.', '', 0),
(19195, 'plPL', 'Cóż, czasem trzeba wziąć sprawy we własne ręce. Balamore shanal!', '', 0),
(20195, 'plPL', 'Energia. Moc. Mój lud jest od niej uzależniony... ta zależność ujawniła się po zniszczeniu Słonecznej Studni. Witajcie w przyszłości. Szkoda, że jesteście za późno, by ją powstrzymać. Teraz nikt mnie nie powstrzyma! Selama ashal\'anore!', '', 0),
(20198, 'plPL', 'Zobaczmy, jak sobie poradzicie, gdy wasz świat stanie na głowie.', '', 0),
(20199, 'plPL', 'Trudno utrzymać się przy ziemi?', '', 0),
(20200, 'plPL', 'Na moc słońca!', '', 0),
(20201, 'plPL', 'Anar\'anel belore!', '', 0),
(20202, 'plPL', 'Słuchaj mnie!', '', 0),
(20204, 'plPL', 'Nie zwyciężycie!', '', 0),
(20205, 'plPL', 'Zaryzykowaliście. I przegraliście.', '', 0),
(20206, 'plPL', 'To była dziecinna igraszka.', '', 0),
(20207, 'plPL', 'Za... Quel\'...Thalas!', '', 0),
(20208, 'plPL', 'Nie zaszedłem tak daleko, by ktoś mnie teraz powstrzymał! Nie pozwolę zagrozić przyszłości, którą zaplanowałem! Teraz zakosztujecie prawdziwej mocy!!', '', 0),
(20372, 'plPL', 'Dość tego! Teraz przyzywam gniew samego kosmosu.', 'Dość tego! Teraz przyzywam gniew samego kosmosu.', 0),
(20373, 'plPL', 'Staję się JEDNYM... z PUSTKĄ!', 'Staję się JEDNYM... z PUSTKĄ!', 0),
(20775, 'plPL', '%s zaczyna rzucać Pirowybuch!', '', 0),
(20847, 'plPL', '', 'Sin\'dorei panują niepodzielnie!', 0),
(20848, 'plPL', '', 'To jeszcze nie koniec!', 0),
(20849, 'plPL', '', 'Tal anu\'men no sin\'dorei!', 0),
(20850, 'plPL', '', 'Ciepło słońca... czeka.', 0),
(20851, 'plPL', '', 'Twoja dusza należy do otchłani!', 0),
(20852, 'plPL', '', 'Na krew Wysoko Urodzonych!', 0),
(20853, 'plPL', '', 'Za Słoneczną Studnię!', 0),
(20854, 'plPL', '', 'Nie macie żadnych szans!', 0),
(20855, 'plPL', '', 'Zmiażdżę wasze urojenia o wielkości!', 0),
(20858, 'plPL', 'NIE! Ja... nie... pozwolę...', '', 0),
(20859, 'plPL', 'Krew za krew!', '', 0),
(20861, 'plPL', 'Kolejne niebezpieczeństwa... czekają...', '', 0),
(20904, 'plPL', 'Wybacz mi, mój książę! Ja... zawiodłem.', '', 0),
(20906, 'plPL', 'Alarm! Zostaliście przeznaczeni do eksterminacji.', '', 0),
(20907, 'plPL', 'Systemy... wyłą... cza... ją... się...', '', 0),
(20908, 'plPL', 'Eksterminacja zakończona powodzeniem.', '', 0),
(20909, 'plPL', 'Inwazyjna forma życia przestała funkcjonować.', '', 0),
(20910, 'plPL', 'Zagrożenie zneutralizowane.', '', 0),
(20911, 'plPL', 'Rozpoczynam środki alternatywne...', '', 0),
(20912, 'plPL', 'Obliczanie parametrów siły...', '', 0),
(35758, 'plPL', 'Przygotujcie się!', '', 0);
